"use client";

import * as React from "react";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { ToggleGroup as ToggleGroupPrimitive } from "@base-ui/react/toggle-group";
import { type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { wellInset } from "./_shared";
import { toggleVariants } from "./toggle";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants>
>({});

/**
 * Burnished ToggleGroup: a row of toggle pills pressed into one recessed
 * well. The pressed pill rises as a graphite bevel; the group passes its
 * variant and size to every item.
 */
function ToggleGroup({
  className,
  variant,
  size,
  children,
  ...props
}: WithClassName<ToggleGroupPrimitive.Props<string>> &
  VariantProps<typeof toggleVariants>) {
  return (
    <ToggleGroupPrimitive
      data-slot="toggle-group"
      className={cn(
        "inline-flex flex-wrap items-center gap-1 rounded-full p-1",
        wellInset,
        "data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch data-[orientation=vertical]:rounded-2xl",
        className,
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size }}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive>
  );
}
ToggleGroup.displayName = "ToggleGroup";

/** One pill inside a ToggleGroup. It takes the group's variant and size unless the group leaves them unset. */
function ToggleGroupItem({
  className,
  variant,
  size,
  ...props
}: WithClassName<TogglePrimitive.Props<string>> &
  VariantProps<typeof toggleVariants>) {
  const context = React.useContext(ToggleGroupContext);

  return (
    <TogglePrimitive
      data-slot="toggle-group-item"
      className={cn(
        toggleVariants({
          variant: context.variant ?? variant,
          size: context.size ?? size,
        }),
        // Inside the group the well is shared, so an outline item drops its own.
        "not-data-[pressed]:bg-none not-data-[pressed]:shadow-none",
        className,
      )}
      {...props}
    />
  );
}
ToggleGroupItem.displayName = "ToggleGroupItem";

export { ToggleGroup, ToggleGroupItem };
